def build():
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "styles.css").write_text(CSS, encoding="utf-8")
    icon = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#08654b"/><path d="M14 45V19l18 17 18-17v26" fill="none" stroke="#e6f19b" stroke-width="6" stroke-linejoin="round"/></svg>'
    (OUT / "favicon.svg").write_text(icon, encoding="utf-8")
    for filename, (title, description, label, content) in pages.items():
        url = BASE + "/" + ("" if filename == "index.html" else filename)
        nav = ''.join('<a href="' + name + '"' + (' aria-current="page"' if name == filename else '') + '>' + page[2] + '</a>' for name, page in pages.items())
        schema = {"@context":"https://schema.org", "@type":"WebPage", "name":title, "description":description,"url":url,"isPartOf":{"@type":"WebSite","name":"OpenMausBot Python MCP Bridge","url":BASE + "/"}}
        if filename == "index.html":
            schema = {"@context":"https://schema.org","@type":"SoftwareSourceCode","name":"OpenMausBot Python MCP Bridge","description":description,"url":url,"codeRepository":REPO,"programmingLanguage":"Python","runtimePlatform":"Windows","license":REPO + "/blob/main/LICENSE","author":{"@type":"Person","name":"Nisith Moragoda","url":"https://github.com/n1s1th"}}
        page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(description, quote=True)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><meta property="og:title" content="{html.escape(title, quote=True)}"><meta property="og:description" content="{html.escape(description, quote=True)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta property="og:site_name" content="OpenMausBot Python MCP Bridge"><meta name="twitter:card" content="summary"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip" href="#main">Skip to content</a><header><nav aria-label="Main navigation"><a class="brand" href="index.html">OpenMausBot <span>PYTHON MCP</span></a>{nav}</nav></header><main id="main" class="{'home' if filename == 'index.html' else 'article'}">{content}</main><footer><p>Independent open-source integration by Nisith Moragoda. Not affiliated with OpenMausBot or OpenAI. MIT licensed.</p><div><a href="{REPO}">GitHub ↗</a><a href="security.html">Security</a><a href="{REPO}/issues">Report an issue</a></div></footer></body></html>'''
        (OUT / filename).write_text(page, encoding="utf-8")
    urls = [BASE + "/" + ("" if path == "index.html" else path) for path in pages]
    (OUT / "sitemap.xml").write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join('<url><loc>' + u + '</loc></url>' for u in urls) + '</urlset>', encoding="utf-8")
    (OUT / "robots.txt").write_text("User-agent: *\nAllow: /\nSitemap: " + BASE + "/sitemap.xml\n", encoding="utf-8")
    (OUT / ".nojekyll").write_text("", encoding="utf-8")
    print(f"Built {len(pages)} pages in {OUT}")

if __name__ == "__main__":
    build()

